/* board_presets.c — turns the patches (patches/NAME.json) into a constant C table for the boards, which have
 * no JSON reader: per preset its name, engine and description, and the parameter values the host applies
 * after selecting the engine (patch_apply: synth parameter id + normalized value). A board that applies them
 * on a fresh synth_init plays the patch as the WAV renders do. Patches of engines that need the shared
 * table memory (wavetables) are left out. Regenerated by every host build; never edit the output by hand.
 *
 *   board_presets PATCH_DIR OUT.c
 */
#include <dirent.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "json.h"
#include "patch.h"

#define MAX_PRESETS 256

static int by_name(const void *a, const void *b) { return strcmp(*(char *const *)a, *(char *const *)b); }

static void c_str(FILE *f, const char *s)
{
    fputc('"', f);
    for (; s && *s; s++) {
        if (*s == '"' || *s == '\\')
            fputc('\\', f);
        if (*s >= ' ' && *s <= '~')
            fputc(*s, f);
    }
    fputc('"', f);
}

static int engine_index(const engine_ops_t *e)
{
    for (int i = 0; i < SYNTH_ENGINE_COUNT; i++)
        if (engine_registry[i] == e)
            return i;
    return -1;
}

int main(int argc, char **argv)
{
    if (argc != 3) {
        fprintf(stderr, "usage: board_presets PATCH_DIR OUT.c\n");
        return 2;
    }
    DIR *d = opendir(argv[1]);
    if (!d) {
        fprintf(stderr, "board_presets: cannot open %s\n", argv[1]);
        return 1;
    }
    char *files[MAX_PRESETS];
    int nf = 0;
    for (struct dirent *e; (e = readdir(d)) && nf < MAX_PRESETS;) {
        const size_t len = strlen(e->d_name);
        if (len > 5 && !strcmp(e->d_name + len - 5, ".json") && strcmp(e->d_name, "index.json"))
            files[nf++] = strdup(e->d_name);
    }
    closedir(d);
    qsort(files, (size_t)nf, sizeof(files[0]), by_name);

    static patch_t p[MAX_PRESETS];
    static char desc[MAX_PRESETS][256];
    int np = 0, skipped = 0;
    for (int i = 0; i < nf; i++) {
        char path[1024], err[512], warn[512];
        snprintf(path, sizeof(path), "%s/%s", argv[1], files[i]);
        if (patch_load(path, &p[np], err, sizeof(err), warn, sizeof(warn)) != 0) {
            fprintf(stderr, "board_presets: %s: %s\n", files[i], err);
            return 1;
        }
        if (p[np].engine->shared_floats > 0) { /* needs the table arena (SDRAM on the board): later */
            skipped++;
            continue;
        }
        json_t *j = json_parse_file(path, err, sizeof(err));
        const json_t *ds = j ? json_get(j, "description") : NULL;
        snprintf(desc[np], sizeof(desc[np]), "%s", ds && ds->type == JSON_STR ? ds->str : "");
        json_free(j);
        np++;
    }

    FILE *f = fopen(argv[2], "w");
    if (!f) {
        fprintf(stderr, "board_presets: cannot write %s\n", argv[2]);
        return 1;
    }
    fprintf(f, "/* presets_gen.c — GENERATED by host/board_presets from patches/NAME.json (every host build):\n"
               " * do not edit. %d presets; %d patches left out (engines that need the wavetable memory). */\n"
               "#include \"presets.h\"\n\n",
            np, skipped);
    fprintf(f, "const preset_param_t preset_params[] = {\n");
    int first = 0;
    for (int i = 0; i < np; i++) {
        fprintf(f, "    /* %s */\n", p[i].name);
        for (int k = 0; k < p[i].n; k++) {
            char num[32];
            snprintf(num, sizeof(num), "%.9g", (double)param_to_norm(p[i].desc[k], p[i].values[k]));
            fprintf(f, "    {%d, %s%sf},\n", p[i].ids[k], num, strpbrk(num, ".e") ? "" : ".0");
        }
    }
    fprintf(f, "};\n\nconst preset_t presets[] = {\n");
    for (int i = 0; i < np; i++) {
        fprintf(f, "    {");
        c_str(f, p[i].name);
        fprintf(f, ", ");
        c_str(f, p[i].engine->name);
        fprintf(f, ", ");
        c_str(f, desc[i]);
        fprintf(f, ", %d, %d, %d},\n", engine_index(p[i].engine), first, p[i].n);
        first += p[i].n;
    }
    fprintf(f, "};\n\nconst int preset_count = %d;\nconst uint32_t preset_catalog = 0x%08Xu; /* catalog_hash() */\n", np, catalog_hash());
    fclose(f);
    for (int i = 0; i < nf; i++)
        free(files[i]);
    return 0;
}
